const { User, Article, Comment } = require("./models");
const {
  findOrCreateByField,
  createRecordsIfEmpty,
} = require("./seed-utils");

const SEED_USERNAME = "u1";
const SEED_ARTICLE_SLUG = "a1";

async function seed() {
  const [user] = await findOrCreateByField(User, "username", SEED_USERNAME);

  const [article] = await findOrCreateByField(
    Article,
    "slug",
    SEED_ARTICLE_SLUG,
    { userId: user.id },
  );

  await createRecordsIfEmpty(Comment, { articleId: article.id }, [
    { body: "c1", articleId: article.id, userId: user.id },
    { body: "c2", articleId: article.id, userId: user.id },
  ]);
}

module.exports = { seed };

